const test=require('node:test'),assert=require('node:assert/strict');
const{fixture,scalar}=require('./harness.cjs');

test('version GC never deletes current heads, closed-day final payloads, or more than its budget',async()=>{const{db,cohort,gc}=await fixture();try{const c=await cohort('2026-10-10',24,{lane:'closed'});await db.exec("insert into private.provider_snapshot_artifacts(job_id,run_id,fence,revision,dependency_token,payload,payload_hash,stored_bytes,provenance,next_due_at)select job_id,gen_random_uuid(),fence,revision,dependency_token,payload,payload_hash,stored_bytes,provenance,next_due_at from private.provider_snapshot_artifacts");const n=await scalar(db,'select count(*)::int from private.provider_snapshot_heads');assert.equal((await gc(3)).artifacts,3);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads'),n);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_jobs'),c.jobs.length);await gc(200);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_artifacts'),n);}finally{await db.close()}});
test('partial newer cutoffs cannot evict last common complete generation; explicit replacement retires only old intraday',async()=>{const h=await fixture(),{db,cohort,retire,gc}=h;try{const old=await cohort('2026-10-10',10),partial=await cohort('2026-10-10',11,{missing:true});assert.equal((await retire(old.id)).status,'no_complete_replacement');const next=await cohort('2026-10-10',12);assert.equal(await scalar(db,'select private.provider_snapshot_cohort_complete($1)',[next.id]),true);const r=await retire(old.id);assert.equal(r.status,'retired');assert.equal(r.heads,10);assert.equal((await retire(next.id)).status,'no_complete_replacement');assert.equal((await retire(old.id)).status,'already_retired');await gc(200);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_jobs where id=any($1::uuid[])',[old.jobs]),0);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads where job_id=any($1::uuid[])',[next.jobs]),10);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads where job_id=any($1::uuid[])',[partial.jobs]),9);}finally{await db.close()}});
test('current building/retry lastgood, recent cutoffs, and daily windows remain protected',async()=>{const{db,cohort,retire}=await fixture();try{const old=await cohort('2026-10-10',10);await cohort('2026-10-10',24,{lane:'closed'});await db.query("update private.provider_snapshot_jobs set status='failed',attempts=1 where id=$1",[old.jobs[0]]);assert.equal((await retire(old.id)).status,'active_jobs_protected');await db.query("update private.provider_snapshot_jobs set status='ready'where id=$1",[old.jobs[0]]);await db.query('update private.provider_snapshot_cohorts set updated_at=clock_timestamp()where id=$1',[old.id]);assert.equal((await retire(old.id)).status,'protected');const daily=await scalar(db,"select id from private.provider_snapshot_cohorts where lane='closed'");assert.equal((await retire(daily)).status,'protected');}finally{await db.close()}});
test('same-day common replacement must match native roster and current semantic dependencies',async()=>{const{db,targets,cohort,retire}=await fixture();try{const old=await cohort('2026-10-10',10);await cohort('2026-10-10',11,{useTargets:[targets[0]]});assert.equal((await retire(old.id)).status,'no_complete_replacement');await cohort('2026-10-10',12);await db.exec("insert into private.dashboard_admin_provider_overrides values('印度','RETENTION_A','raw','changed',1)");assert.equal((await retire(old.id)).status,'no_complete_replacement');assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads where job_id=any($1::uuid[])',[old.jobs]),10);}finally{await db.close()}});
test('shared previous-period slots survive retirement and all routines deny browser roles',async()=>{const{db,cohort,retire,gc}=await fixture();try{const old=await cohort('2026-10-10',10);await cohort('2026-10-10',11);const following=await cohort('2026-10-11',10);assert.equal((await retire(old.id)).heads,6);await gc(200);assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads where job_id=any($1::uuid[])',[following.jobs]),10);for(const role of ['anon','authenticated','service_role'])for(const fn of ['provider_snapshot_retire_intraday(uuid)','provider_snapshot_gc_versions(integer)','provider_snapshot_cohort_complete(uuid)'])assert.equal(await scalar(db,'select has_function_privilege($1,$2,\'execute\')',[role,'private.'+fn]),false);await assert.rejects(()=>gc(201),/invalid_snapshot_gc_budget/);}finally{await db.close()}});

test('unexpected old cohort membership never retires an unrelated head',async()=>{const{db,cohort,retire}=await fixture();try{const old=await cohort('2026-10-10',10),next=await cohort('2026-10-10',12);await db.query('delete from private.provider_snapshot_cohort_jobs where cohort_id=$1 and job_id=$2',[old.id,old.jobs[0]]);await db.query('insert into private.provider_snapshot_cohort_jobs values($1,$2)',[old.id,next.jobs[0]]);assert.equal((await retire(old.id)).status,'invalid_cohort_membership');assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads'),20);}finally{await db.close()}});
test('expired artifact deadline cannot qualify a replacement, while completed closed-day final without deadline can',async()=>{const{db,cohort,retire}=await fixture();try{const old=await cohort('2026-10-10',10);await cohort('2026-10-10',12,{nextDue:'2026-10-11T00:00:00Z'});assert.equal((await retire(old.id)).status,'no_complete_replacement');assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads where job_id=any($1::uuid[])',[old.jobs]),10);await cohort('2026-10-10',24,{lane:'closed'});assert.equal((await retire(old.id)).status,'retired');}finally{await db.close()}});
test('today replacement older than reader 30-minute cutoff retains previous lastgood',async t=>{const{db,cohort,retire}=await fixture();try{const clock=(await db.query("select to_char(statement_timestamp()at time zone'Asia/Kolkata','YYYY-MM-DD')as local_day,extract(hour from statement_timestamp()at time zone'Asia/Kolkata')::int as local_hour")).rows[0];if(clock.local_hour<3){t.skip('No two positive whole-hour windows older than30min exist yet today');return;}const old=await cohort(clock.local_day,clock.local_hour-2);await cohort(clock.local_day,clock.local_hour-1);assert.equal((await retire(old.id)).status,'no_complete_replacement');assert.equal(await scalar(db,'select count(*)::int from private.provider_snapshot_heads where job_id=any($1::uuid[])',[old.jobs]),10);}finally{await db.close()}});
